    'RegisterSimpleRisk'=>'Εγγραφή του SimpleRisk',
    'RegistrationText'=>'Οι εγγεγραμμένες παρουσίες του SimpleRisk αποκτούν άμεσα πρόσβαση στα Extras Αναβάθμισης και Secure Controls Framework (SCF). Το Extra Αναβάθμισης παρέχει τη δυνατότητα δημιουργίας αντιγράφου ασφαλείας και αναβάθμισης της παρουσίας του SimpleRisk με το πάτημα ενός κουμπιού. Το Extra Secure Controls Framework (SCF) παρέχει ένα κοινό πλαίσιο ελέγχου που είναι ενσωματωμένο στη λειτουργικότητα Διακυβέρνησης του SimpleRisk. Κατά την εγγραφή του SimpleRisk, οι πληροφορίες εγγραφής σας θα σταλούν σε διακομιστή που φιλοξενείται από το SimpleRisk. Οι πληροφορίες εγγραφής που παρέχονται θα χρησιμοποιηθούν από το SimpleRisk για να ειδοποιεί τους πελάτες για νέες εκδόσεις και ενημερώσεις ασφαλείας. Η εγγραφή του SimpleRisk σας εντάσσει στις επικοινωνίες μάρκετινγκ μας, αλλά μπορείτε να εξαιρεθείτε ανά πάσα στιγμή χρησιμοποιώντας τον σύνδεσμο διαγραφής συνδρομής σε αυτές τις επικοινωνίες. Το SimpleRisk σέβεται την ιδιωτικότητα των πελατών μας και οι πληροφορίες που μας παρέχονται μέσω της διαδικασίας εγγραφής του SimpleRisk δεν θα πωληθούν ποτέ σε τρίτους.',
