    'HealthCheckDesc'                     => 'Διάγνωση της κατάστασης του συστήματος: έκδοση PHP, επεκτάσεις, δικαιώματα αρχείων, συνδεσιμότητα βάσης δεδομένων, πρόγραμμα cron και ενεργοποιήσεις των Extras.',
    'AnnouncementsDesc'                   => 'Σύνταξη και διαχείριση ανακοινώσεων banner που είναι ορατές σε όλους τους χρήστες.',
    'RegisterAndUpgradeDesc'              => 'Καταχωρίστε την εγκατάσταση SimpleRisk, εισαγάγετε ή ανανεώστε ένα κλειδί συνδρομής και ενεργοποιήστε τις αναβαθμίσεις Core/Extra με ένα κλικ.',
    'QueueMonitorDesc'                    => 'Επιθεωρήστε την ουρά εργασιών παρασκηνίου: εκκρεμείς, σε εξέλιξη και αποτυχημένες εργασίες.',
    'ExtrasDesc'                          => 'Ενεργοποίηση, απενεργοποίηση και διαμόρφωση των SimpleRisk Extras (πρόσθετα επί πληρωμή).',
    'ArtificialIntelligenceExtraDesc'     => 'Το Extra Τεχνητής Νοημοσύνης παρέχει βελτιωμένη ανάλυση κινδύνου (συμπεριλαμβανομένων των αξιολογήσεων FAIR) και προσαρμοσμένη τεκμηρίωση.',
    'CustomizationExtraDesc'              => 'Το Extra Προσαρμογής παρέχει τη δυνατότητα προσθήκης και αφαίρεσης διαφορετικών τύπων πεδίων και δυναμικής δημιουργίας προσαρμοσμένων προτύπων σελίδων.',
    'NotificationExtraDesc'               => 'Το Extra Ειδοποιήσεων Email επιτρέπει στο SimpleRisk να στέλνει ειδοποιήσεις email όταν οι κίνδυνοι υποβάλλονται, τροποποιούνται ή υφίστανται με άλλον τρόπο ενέργειες. Αυτό το Extra μπορεί επίσης να προστεθεί ως προγραμματισμένο σενάριο για την αποστολή τακτικών υπενθυμίσεων όταν οι κίνδυνοι είναι έτοιμοι για επανεξέταση από τη διαχείριση. Στο προϊόν SimpleRisk Core, χωρίς αυτό το Extra, δεν κοινοποιούνται ειδοποιήσεις εκτός του ίδιου του εργαλείου.',
    'VulnerabilityManagementExtraDesc'    => 'Το Extra Διαχείρισης Ευπαθειών παρέχει στους πελάτες τη δυνατότητα να ενσωματώσουν την παρουσία SimpleRisk τους με Qualys, Tenable.io ή Rapid7 Nexpose/InsightVM και να εισαγάγουν στο SimpleRisk δεδομένα τόσο περιουσιακών στοιχείων όσο και ευπαθειών. Από εκεί, μπορείτε να επιλέξετε ποιους ιστότοπους θέλετε να καλύψετε, να καθορίσετε ποιες βαθμολογίες ευπαθειών θα εισαχθούν και να διαλέξετε ποιες ευπάθειες μετατρέπονται σε κινδύνους ώστε να παρακολουθούνται.',
    'IncidentManagementExtraDesc'         => 'Το Incident Management Extra βασίζεται στον Οδηγό Χειρισμού Συμβάντων Ασφάλειας Υπολογιστών NIST 800-61 και παρέχει δυνατότητες διαχείρισης συμβάντων μέσα από το σύστημα SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Μετονομάστε την ορολογία του SimpleRisk (Κίνδυνος, Περιουσιακό Στοιχείο, Πλαίσιο, κ.λπ.) σε όλο το περιβάλλον χρήστη.',
    'RiskConfigurationDesc'               => 'Διαμορφώστε τους κανόνες βαθμολόγησης κινδύνου: επίπεδα, όρεξη, όρια SLA και τους κλασικούς/συμβάλλοντες τύπους κινδύνου.',
    'RiskAndThreatCatalogDesc'            => 'Διατηρήστε τον κατάλογο τιμών κινδύνου και απειλής που χρησιμοποιούνται στα αναπτυσσόμενα μενού.',
    'AddAndRemoveValuesDesc'              => 'Διαχειριστείτε τις τιμές αναπτυσσόμενης λίστας για τα πεδία κινδύνου: τοποθεσία, πηγή, κατηγορία, ομάδα, τεχνολογία και άλλα.',
    'AssetValuationDesc'                  => 'Διαμορφώστε την κλίμακα αποτίμησης περιουσιακών στοιχείων και τις παρακάμψεις αποτίμησης ανά περιουσιακό στοιχείο.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Προσθήκη, επεξεργασία, απενεργοποίηση και επαναφορά χρηστών· διαχείριση πολιτικής κωδικών πρόσβασης.',
    'RoleManagementDesc'                  => 'Ορίστε ρόλους και τα δικαιώματα που παρέχει κάθε ρόλος.',
    'TeamManagementDesc'                  => 'Δημιουργήστε και διαχειριστείτε ομάδες που χρησιμοποιούνται για φιλτράρισμα ορατότητας εγγραφών.',
    'SeparationExtraDesc'                 => 'Το Team-Based Separation Extra περιορίζει την προβολή κινδύνων μόνο στους χρήστες που είναι μέλη της ομάδας στην οποία έχει ανατεθεί ο κίνδυνος. Στο προϊόν SimpleRisk Core, χωρίς αυτό το Extra, κάθε χρήστης μπορεί να δει κάθε κίνδυνο.',
    'CustomAuthenticationExtraDesc'       => 'Το Extra Προσαρμοσμένου Ελέγχου Ταυτότητας παρέχει υποστήριξη για έλεγχο ταυτότητας Active Directory και SAML. Στο προϊόν SimpleRisk Core, χωρίς αυτό το Extra, η μόνη επιλογή είναι η δημιουργία νέων χρηστών στο αποθετήριο ταυτοτήτων του SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Το Encrypted Database Extra δημιουργεί ένα τυχαίο κλειδί κρυπτογράφησης AES-256 bit και στη συνέχεια το χρησιμοποιεί για την κρυπτογράφηση ευαίσθητου κειμένου πριν από την εισαγωγή του στη βάση δεδομένων SimpleRisk. Αυτό εμποδίζει οποιονδήποτε να δει ή να τροποποιήσει τα δεδομένα χωρίς να χρησιμοποιήσει απευθείας την εφαρμογή SimpleRisk.',
    'OrganizationManagementDesc'          => 'Το Extra Οργανωτικής Ιεραρχίας παρέχει τη δυνατότητα ορισμού πολλαπλών επιχειρηματικών μονάδων που μπορούν να περιλαμβάνουν οποιονδήποτε αριθμό ομάδων. Οι χρήστες μπορούν στη συνέχεια να ανατεθούν σε μία ή περισσότερες ομάδες υπό διάφορες επιχειρηματικές μονάδες. Αυτό επηρεάζει τη δυνατότητα ενός χρήστη να βλέπει και να χρησιμοποιεί τις ομάδες, τους χρήστες και τα περιουσιακά στοιχεία με τα οποία δεν σχετίζεται.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Μαζική διαγραφή κινδύνων. Χρησιμοποιήστε με φειδώ — οι διαγραφές είναι μόνιμες.',
    'AuditTrailDesc'                      => 'Αναζήτηση και εξαγωγή του αρχείου καταγραφής ελέγχου συστήματος των ενεργειών των χρηστών.',
    'ImportExportExtraDesc'               => 'Το Extra Εισαγωγής-Εξαγωγής παρέχει τη δυνατότητα εισαγωγής δεδομένων στο SimpleRisk μέσω αντιστοίχισης πεδίων ενός αρχείου CSV με πεδία της βάσης δεδομένων του SimpleRisk. Μπορεί να χρησιμοποιηθεί για την εισαγωγή αποτελεσμάτων ελέγχου από υπολογιστικό φύλλο τρίτου, αποτελεσμάτων σάρωσης ευπαθειών από άλλο εργαλείο, περιουσιακών στοιχείων από το CMDB σας και άλλα. Το Extra παρέχει επίσης τη δυνατότητα εξαγωγής αρχείων CSV από το SimpleRisk που περιέχουν κινδύνους, μετριασμούς, επανεξετάσεις ή μια συνδυαστική αναφορά και των τριών.',
    'JiraExtraDesc'                       => 'Το Extra Ενσωμάτωσης Jira παρέχει στους χρήστες τη δυνατότητα αμφίδρομης ενσωμάτωσης με μια παρουσία Jira. Επιτρέπει τη σύνδεση κινδύνων με θέματα Jira, καθώς και τον συγχρονισμό των δεδομένων, της κατάστασης και των σχολίων τους.',
    'APIExtraDesc'                        => 'Το API Extra επιτρέπει στους πελάτες να χρησιμοποιούν ένα RESTful API για να δημιουργούν αλληλεπιδράσεις με άλλες εφαρμογές βάσει σεναρίων, ώστε να αποκτήσουν προηγμένο αυτοματισμό και να αξιοποιήσουν την υπάρχουσα υποδομή.',
    'AdvancedSearchExtraDesc'             => 'Το Extra Σύνθετης Αναζήτησης μετατρέπει το πλαίσιο αναζήτησης της επάνω γραμμής σε μία αναζήτηση σε κινδύνους, πλαίσια, ελέγχους (controls), έγγραφα, εξαιρέσεις, δοκιμές, ελέγχους (audits), περιουσιακά στοιχεία και ομάδες περιουσιακών στοιχείων, με μια πλήρη σελίδα αναζήτησης για την επεξεργασία των αποτελεσμάτων. Εμφανίζει μόνο τις εγγραφές που επιτρέπεται να βλέπει ο χρήστης.',
    'AssessmentsExtraDesc'                => 'Το Extra Αξιολόγησης Κινδύνου παρέχει στους χρήστες τη δυνατότητα να ορίζουν επαφές, να δημιουργούν ερωτήσεις (συμπεριλαμβανομένης της λογικής), να συνθέτουν πολλαπλές ερωτήσεις με ένα πρότυπο ερωτηματολογίου, να δημιουργούν ερωτηματολόγια και να τα στέλνουν σε επαφές, να βλέπουν τα αποτελέσματα ερωτηματολογίου, να προσθέτουν κινδύνους βάσει αυτών των αποτελεσμάτων, να συγκρίνουν τα αποτελέσματα με την πάροδο του χρόνου, να εισάγουν και να εξάγουν εξωτερικά προσαρμοσμένες αξιολογήσεις και να επανεξετάζουν το ίχνος ελέγχου της αξιολόγησης κινδύνου.',
    'ActiveAssessmentsDesc'               => 'Προβολή και διαχείριση αξιολογήσεων που βρίσκονται σε εξέλιξη.',
    'WorkflowsExtraDesc'                  => 'Το Extra Ροών Εργασίας παρέχει μια οπτική μηχανή ροών εργασίας βάσει συμβάντων που αυτοματοποιεί ενέργειες διαχείρισης κινδύνου ως απάντηση σε συμβάντα εντός του SimpleRisk. Μπορείτε να σχεδιάσετε ροές εργασίας που ενεργοποιούνται από αλλαγές — όπως η υποβολή, η ενημέρωση ή η επανεξέταση ενός κινδύνου — για τη δρομολόγηση εγκρίσεων, την ανάθεση εργασιών και τη διατήρηση της ροής της διαδικασίας χωρίς χειροκίνητη παρέμβαση.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "Το Secure Controls Framework (SCF) Extra αποτελεί άμεση ενσωμάτωση μεταξύ του Secure Controls Framework και του SimpleRisk. Εισάγει τον κατάλογο ελέγχων του SCF και τις αντιστοιχίσεις τους σε ένα ευρύ φάσμα πλαισίων συμμόρφωσης και κυβερνοασφάλειας στη λειτουργικότητα Διακυβέρνησης του SimpleRisk, ώστε να μπορείτε να υιοθετήσετε τα πλαίσια που χρειάζεστε και να διαχειριστείτε τους ελέγχους τους χωρίς να τα δημιουργήσετε χειροκίνητα.",

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Μετεγκατάσταση παλαιών στηλών ημερομηνίας επανεξέτασης τύπου varchar σε κατάλληλους τύπους ημερομηνίας. Ορατό μόνο όταν χρειάζεται.',
    'DatabaseUpgradeDesc'                 => 'Ενεργοποιήστε χειροκίνητα τη ρουτίνα αναβάθμισης της βάσης δεδομένων SimpleRisk.',

