    'InstallExtraTitle'                          => 'Εγκατάσταση Extra',
    'InstallExtraBody'                           => 'Εγκατάσταση του Extra {name}; Θα γίνει λήψη του πακέτου από το SimpleRisk και αποσυμπίεσή του στην εγκατάστασή σας. Η ενεργοποίηση είναι ξεχωριστό βήμα που μπορείτε να κάνετε από το πλακίδιο μετά την ολοκλήρωση της εγκατάστασης.',
    'InstallExtraError'                          => 'Αποτυχία εγκατάστασης του Extra. Ελέγξτε τη σελίδα Ελέγχου εύρυθμης λειτουργίας για διαγνωστικά.',
