    'DeletedAssessmentsCannotBeRecovered' => 'Δεν είναι δυνατή η ανάκτηση των διαγραμμένων αξιολογήσεων',
    'TheAssessmentsWereDeletedSuccessfully' => 'Οι αξιολογήσεις διαγράφηκαν με επιτυχία.',
    'AssetValuationMode' => 'Λειτουργία Αποτίμησης Περιουσιακών Στοιχείων',
    'AutomaticLinearRange' => 'Αυτόματο γραμμικό εύρος',
    'AutomaticExponentialRange' => 'Αυτόματο Εκθετικό Εύρος',
    'ManualValuation' => 'Χειροκίνητο',
    'AssetValuationMinMustBeNonNegative' => 'Η ελάχιστη αποτίμηση περιουσιακών στοιχείων πρέπει να είναι μηδέν ή μεγαλύτερη για το Αυτόματο Εκθετικό Εύρος.',
    'Preferences' => 'Προτιμήσεις',
    'SpecificUser' => 'Συγκεκριμένος χρήστης',
    'SpecificUsers' => 'Συγκεκριμένοι χρήστες',
    'Help' => 'Βοήθεια',
    'Profile' => 'Προφίλ',
    'Scoring' => 'Βαθμολόγηση',
    'EncryptionMissingLockTablesPrivilege'   => 'Ο χρήστης της βάσης δεδομένων του SimpleRisk δεν διαθέτει το δικαίωμα LOCK TABLES, το οποίο είναι απαιτούμενο για την ασφαλή κρυπτογράφηση της βάσης δεδομένων. Ζητήστε από έναν διαχειριστή της βάσης δεδομένων να εκτελέσει τη δήλωση GRANT που επιστρέφεται στην απάντηση και δοκιμάστε ξανά.',
    'EncryptionMissingLockTablesPrivilegeUi' => 'Ο χρήστης της βάσης δεδομένων του SimpleRisk δεν διαθέτει το δικαίωμα LOCK TABLES που απαιτείται για την κρυπτογράφηση. Ένας διαχειριστής της βάσης δεδομένων πρέπει να εκτελέσει: GRANT LOCK TABLES ON {$db}.* TO {$user}; και μετά να δοκιμάσει ξανά.',
    'EncryptionRequiredGrantLabel' => 'Απαιτούμενη δήλωση GRANT:',
    'EncryptionActivationAlreadyRunning' => 'Μια ενεργοποίηση κρυπτογράφησης βρίσκεται ήδη σε εξέλιξη. Περιμένετε να ολοκληρωθεί ή χρησιμοποιήστε την επαναφορά από αντίγραφο ασφαλείας για ανάκτηση.',
    'EncryptionActivationEnqueued'           => 'Η ενεργοποίηση του Extra κρυπτογράφησης τέθηκε σε ουρά. Το περιβάλλον διαχείρισης θα παρακολουθεί την πρόοδο ενώ η βάση δεδομένων κρυπτογραφείται.',
    'EncryptionActivationEnqueueFailed'      => 'Αποτυχία προσθήκης στην ουρά της εργασίας ενεργοποίησης κρυπτογράφησης. Ελέγξτε το αρχείο καταγραφής εντοπισμού σφαλμάτων για λεπτομέρειες.',
    'EncryptionDeactivationEnqueued'         => 'Η απενεργοποίηση του Extra κρυπτογράφησης τέθηκε σε ουρά. Το περιβάλλον διαχείρισης θα παρακολουθεί την πρόοδο ενώ η βάση δεδομένων αποκρυπτογραφείται.',
    'EncryptionDeactivationEnqueueFailed'    => 'Αποτυχία προσθήκης στην ουρά της εργασίας απενεργοποίησης κρυπτογράφησης. Ελέγξτε το αρχείο καταγραφής εντοπισμού σφαλμάτων για λεπτομέρειες.',
    'EncryptionPipelineInProgress'           => 'Μια διαδικασία κρυπτογράφησης (ενεργοποίηση, απενεργοποίηση ή επαναφορά) βρίσκεται αυτήν τη στιγμή σε εξέλιξη. Περιμένετε να ολοκληρωθεί πριν προσπαθήσετε ξανά.',
    'EncryptionPipelineInProgressTask'       => 'Μια διαδικασία κρυπτογράφησης βρίσκεται αυτήν τη στιγμή σε εξέλιξη (εργασία #{id}, {type}). Περιμένετε να ολοκληρωθεί πριν προσπαθήσετε ξανά.',
    'EncryptionInFlightTitle'            => 'Λειτουργία κρυπτογράφησης σε εξέλιξη',
    'EncryptionInFlightBody'             => 'Μια διαδικασία ενεργοποίησης, απενεργοποίησης ή επαναφοράς κρυπτογράφησης εκτελείται αυτή τη στιγμή. Περιμένετε να ολοκληρωθεί — η σελίδα θα ανανεωθεί αυτόματα όταν ολοκληρωθεί η λειτουργία — πριν δοκιμάσετε ξανά.',
