    'EncryptionRestoreInProgress'           => 'Γίνεται επαναφορά της βάσης δεδομένων του SimpleRisk από αντίγραφο ασφαλείας. Αυτό μπορεί να διαρκέσει αρκετά λεπτά.',
    'EncryptionRestoreEnqueueFailed'        => 'Αποτυχία έναρξης της επαναφοράς. Ελέγξτε τα αρχεία καταγραφής του SimpleRisk και δοκιμάστε ξανά.',
