    'SoaEvidencePolicy' => 'Πολιτική',
    'SoaEvidenceStandard' => 'Πρότυπο',
    'SoaEvidenceProcedure' => 'Διαδικασία',
    'SoaEvidenceGuideline' => 'Κατευθυντήρια γραμμή',
    // ── The legend, grouped by column (SOA_LEGEND_GROUPS, includes/soa.php) ──
