    'SoaEvidenceDesignDocument' => 'Έγγραφο σχεδιασμού',
    'SoaLegendEvidenceDocument' => 'Ένα έγγραφο διακυβέρνησης που επιβεβαιώνεται ως τεκμήριο για αυτόν τον έλεγχο -- αφορά τον σχεδιασμό του και όχι τη λειτουργία του. Ένα έγγραφο δεν φέρει κρίση, γι\' αυτό δεν επισημαίνεται με τικ.',
    // The XLSX export's first worksheet tab. The workbook's other four tabs reuse
