    'AssetScoring' => 'Βαθμολόγηση Περιουσιακών Στοιχείων',
    'AssetScoringSettingsHint' => 'Κάθε περιουσιακό στοιχείο αξιολογείται ως Χαμηλό, Μέτριο ή Υψηλό ως προς την εμπιστευτικότητα, την ακεραιότητα και τη διαθεσιμότητα, ενώ η εμπιστευτικότητα μπορεί εναλλακτικά να είναι Μη εφαρμόσιμη, οπότε εξαιρείται και από τα δύο αποτελέσματα. Η κατηγοριοποίησή του κατά FIPS είναι η υψηλότερη από τις τρεις αξιολογήσεις. Η σταθμισμένη βαθμολογία του είναι ο σταθμισμένος μέσος όρος των τριών τιμών επιπέδου και τα όρια των ζωνών μετατρέπουν αυτή τη βαθμολογία σε ζώνη Χαμηλή, Μέτρια ή Υψηλή. Η αλλαγή αυτών των ρυθμίσεων επαναβαθμολογεί αμέσως κάθε περιουσιακό στοιχείο.',
    'Weights' => 'Βάρη',
    'AssetScoringWeightsHint' => 'Πόσο μετράει κάθε στόχος στη σταθμισμένη βαθμολογία: από 0 έως 100, με έως δύο δεκαδικά ψηφία. Βάρος 0 εξαιρεί τον συγκεκριμένο στόχο. Η ακεραιότητα και η διαθεσιμότητα δεν μπορούν να έχουν και οι δύο βάρος 0, επειδή η εμπιστευτικότητα Μη εφαρμόσιμη εξαιρείται πάντοτε.',
    'LevelValues' => 'Τιμές επιπέδου',
    'AssetScoringLevelValuesHint' => 'Ο αριθμός που συνεισφέρει κάθε αξιολόγηση στη σταθμισμένη βαθμολογία: μεγαλύτερος από 0 και έως 100, με έως δύο δεκαδικά ψηφία, με Χαμηλό μικρότερο από Μέτριο και Μέτριο μικρότερο από Υψηλό. Οι προεπιλογές είναι Χαμηλό 1, Μέτριο 2 και Υψηλό 3.',
    'BandThresholds' => 'Κατώφλια ζώνης',
    'AssetScoringBandThresholdsHint' => 'Μια σταθμισμένη βαθμολογία ίση ή μεγαλύτερη από ένα όριο ανήκει στη συγκεκριμένη ζώνη, ενώ μια βαθμολογία κάτω από το όριο Μέτριο ανήκει στη ζώνη Χαμηλό. Η ζώνη Μέτριο πρέπει να ξεκινά πάνω από την τιμή Χαμηλό και η ζώνη Υψηλό πρέπει να ξεκινά πάνω από τη ζώνη Μέτριο και όχι πάνω από την τιμή Υψηλό.',
    'ModerateStartsAt' => 'Το Μέτριο ξεκινά από',
