    'DefaultScoringForNewAssets' => 'Προεπιλεγμένη βαθμολόγηση για νέα περιουσιακά στοιχεία',
    'AssetScoringDefaultsHint' => 'Προεπιλέγει αυτές τις αξιολογήσεις όταν κάποιος κάνει προσθήκη περιουσιακού στοιχείου στη φόρμα περιουσιακών στοιχείων. Τα περιουσιακά στοιχεία που δημιουργούνται μέσω ανακάλυψης, εισαγωγής ή του API παραμένουν αβαθμολόγητα, εκτός αν παρέχουν τις δικές τους αξιολογήσεις. Αφήστε και τα τρία ως Μη ορισμένο για να απενεργοποιήσετε αυτή τη λειτουργία.',
    'AssetScoringWeightsInvalid' => 'Τα βάρη της Βαθμολόγησης Περιουσιακών Στοιχείων πρέπει να είναι αριθμοί από 0 έως 100 με το πολύ δύο δεκαδικά ψηφία, και η ακεραιότητα και η διαθεσιμότητα δεν μπορούν να έχουν και οι δύο βάρος 0.',
    'AssetScoringValuesInvalid' => 'Οι τιμές επιπέδου της Βαθμολόγησης Περιουσιακών Στοιχείων πρέπει να είναι αριθμοί μεγαλύτεροι από 0 και έως 100 με το πολύ δύο δεκαδικά ψηφία, με Χαμηλό μικρότερο από Μέτριο και Μέτριο μικρότερο από Υψηλό.',
    'AssetScoringThresholdsInvalid' => 'Τα όρια ζωνών της Βαθμολόγησης Περιουσιακών Στοιχείων πρέπει να έχουν το πολύ δύο δεκαδικά ψηφία, με το Μέτριο να ξεκινά πάνω από την τιμή Χαμηλό, το Υψηλό να ξεκινά πάνω από το Μέτριο και το Υψηλό να ξεκινά όχι πάνω από την τιμή Υψηλό.',
    'AssetScoringDefaultsInvalid' => 'Η προεπιλεγμένη βαθμολόγηση για νέα περιουσιακά στοιχεία πρέπει να είναι ένα επίπεδο που προσφέρει κάθε στόχος.',
