    'AssetScoringCategorizationHelp' => 'Η κατηγοριοποίηση ασφάλειας FIPS 199 είναι η μέγιστη τιμή (high-water mark): η υψηλότερη αξιολόγηση μεταξύ των στόχων που εφαρμόζονται. Μία μόνο αξιολόγηση Υψηλός κάνει το περιουσιακό στοιχείο Υψηλό, ανεξάρτητα από τις υπόλοιπες. Το Μη εφαρμόσιμο αγνοείται.',
    'AssetScoringBandHelp' => 'Η ζώνη τοποθετεί τη σταθμισμένη βαθμολογία σε κλίμακα Χαμηλή, Μέτρια ή Υψηλή. Μια βαθμολογία κάτω από {$moderate} είναι Χαμηλή, από {$moderate} έως {$highAt} είναι Μέτρια και {$highAt} ή περισσότερο είναι Υψηλή. Τα όρια διαμορφώνονται στις Προτιμήσεις.',
