    'UserImportPasswordsUnavailable' => 'Οι προσωρινοί κωδικοί πρόσβασης δεν μπορούν πλέον να εμφανιστούν. Εμφανίζονται μία φορά, μόνο στον διαχειριστή που ξεκίνησε την εισαγωγή και μόνο στην καρτέλα του προγράμματος περιήγησης από την οποία ξεκίνησε, και το SimpleRisk δεν διατηρεί τίποτα που θα μπορούσε να τους εμφανίσει ξανά. Ορίστε νέο κωδικό πρόσβασης για κάθε νέο χρήστη επεξεργαζόμενοι τον χρήστη.',
    'UserImportBackgroundNote' => 'Αυτή η σελίδα ενημερώνεται από μόνη της και η εισαγωγή συνεχίζει να εκτελείται αν φύγετε. Ανοίξτε ξανά τη σελίδα για να δείτε το αποτέλεσμα.',
    'AuditAdditionalStakeholdersSetOnTest' => 'Οι πρόσθετοι ενδιαφερόμενοι ορίζονται στη δοκιμή. Για να τους αλλάξετε, επεξεργαστείτε τη δοκιμή στη σελίδα {$page}· η αλλαγή εφαρμόζεται άμεσα σε αυτόν τον έλεγχο.',
    'QuestionnaireDraftSomeFilesNotSaved' => 'Οι απαντήσεις σας αποθηκεύτηκαν, αλλά ένα ή περισσότερα συνημμένα δεν αποθηκεύτηκαν. Ένα αρχείο μπορεί να είναι πολύ μεγάλο ή να είναι τύπου που δεν επιτρέπεται.',
    'UploadFileTooBigForDatabase' => 'Το μεταφορτωμένο αρχείο είναι πολύ μεγάλο για να το αποθηκεύσει η βάση δεδομένων. Ένας διαχειριστής του SimpleRisk μπορεί να αυξήσει τις τιμές max_allowed_packet και innodb_log_file_size στη διαμόρφωση MySQL.',
    'UploadErrorIniSize' => 'Το μεταφορτωμένο αρχείο υπερβαίνει την οδηγία upload_max_filesize στο php.ini.',
    'UploadErrorFormSize' => 'Το μεταφορτωμένο αρχείο υπερβαίνει την οδηγία MAX_FILE_SIZE που καθορίστηκε στη φόρμα HTML.',
    'UploadErrorPartial' => 'Το αρχείο που μεταφορτώθηκε μεταφορτώθηκε μόνο εν μέρει.',
    'UploadErrorNoFile' => 'Δεν μεταφορτώθηκε κανένα αρχείο.',
    'UploadErrorNoTmpDir' => 'Λείπει ένας προσωρινός φάκελος.',
    'UploadErrorCantWrite' => 'Αποτυχία εγγραφής αρχείου στον δίσκο.',
    'UploadErrorExtension' => 'Μια επέκταση PHP διέκοψε τη μεταφόρτωση του αρχείου.',
    'MaxUploadSizeNeedsInteger' => 'Το μέγιστο μέγεθος αρχείου μεταφόρτωσης πρέπει να είναι ακέραιος αριθμός byte μεγαλύτερος από το μηδέν.',
    'MaxUploadSizeUpdated' => 'Το μέγιστο μέγεθος αρχείου μεταφόρτωσης ενημερώθηκε με επιτυχία.',
    'MaxUploadSizeCapped' => 'Η αποθηκευμένη τιμή είναι υψηλότερη από αυτήν που επιτρέπει αυτός ο διακομιστής, επομένως τα μεγαλύτερα αρχεία δεν γίνονται δεκτά μέχρι να αυξηθούν τα όρια PHP και MySQL ή να μειωθεί αυτή η τιμή. Το μεγαλύτερο αρχείο που γίνεται δεκτό αυτήν τη στιγμή, σε bytes:',
    'PleaseEnterAValidEmailAddress' => 'Παρακαλώ εισάγετε μια έγκυρη διεύθυνση ηλεκτρονικού ταχυδρομείου.',
    'RiskImportedClosedWithoutCloseReason' => 'Ο κίνδυνος {$risk_id} ("{$subject}") εισήχθη με κατάσταση Κλειστός αλλά χωρίς Λόγο κλεισίματος, επομένως οι πληροφορίες κλεισίματός του είναι ελλιπείς. Προσθέστε έναν Λόγο κλεισίματος στο αρχείο και εισαγάγετέ το ξανά ή ολοκληρώστε το κλείσιμο από τη σελίδα του κινδύνου.',
    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'Ενεργοποίηση HTTP Strict Transport Security (HSTS)',
    'EnableHSTSHelp' => 'Ειδοποιεί τα προγράμματα περιήγησης να συνδέονται στο SimpleRisk μόνο μέσω HTTPS για τη μέγιστη διάρκεια που ορίζεται παρακάτω. Ενεργοποιήστε το μόνο αφού το HTTPS λειτουργεί αξιόπιστα σε αυτόν τον ιστότοπο: τα προγράμματα περιήγησης που έχουν δει την κεφαλίδα θα απορρίπτουν το απλό HTTP και ένα προβληματικό πιστοποιητικό δεν μπορεί να παρακαμφθεί μέχρι να λήξει η μέγιστη διάρκεια. Ξεκινήστε με μικρή μέγιστη διάρκεια, όπως 300 δευτερόλεπτα, και αυξήστε την αφού επαληθευτεί το HTTPS.',
    'HSTSMaxAge' => 'Μέγιστη διάρκεια HSTS (δευτερόλεπτα)',
    'HSTSMaxAgeInvalid' => 'Η μέγιστη διάρκεια HSTS πρέπει να είναι ακέραιος αριθμός δευτερολέπτων μεταξύ 0 και 63072000.',
    'HSTSIncludeSubdomains' => 'Εφαρμογή HSTS σε όλους τους υποτομείς',
    'HSTSIncludeSubdomainsHelp' => 'Επιβάλλει επίσης HTTPS σε κάθε υποτομέα αυτού του κεντρικού υπολογιστή. Αφήστε το απενεργοποιημένο εάν κάποιος υποτομέας εξυπηρετείται μέσω απλού HTTP.',
    'UpgradeNotificationTitle' => 'Το SimpleRisk έχει αναβαθμιστεί',
    'UpgradeNotificationBody' => 'Το SimpleRisk αναβαθμίστηκε στην έκδοση {$version}. Δείτε τις σημειώσεις έκδοσης για να μάθετε τι έχει αλλάξει.',
    'QuestionnaireStaleClientRefresh' => 'Ανανεώστε αυτήν τη σελίδα για να συνεχίσετε την αυτόματη αποθήκευση της προόδου σας.',
    'SamlLoginRejectedTitle' => 'Η σύνδεση δεν μπόρεσε να ολοκληρωθεί',
    'SamlLoginRejectedMessage' => 'Η απάντηση από τον πάροχο ταυτότητάς σας δεν έγινε δεκτή, επομένως δεν έχετε συνδεθεί. Επιστρέψτε στη σελίδα σύνδεσης και δοκιμάστε ξανά. Εάν το πρόβλημα επιμένει, επικοινωνήστε με τον διαχειριστή του SimpleRisk.',
    'SamlLoginRejectedReference' => 'Αναφορά: {$id}',
