    'QuestionnaireCompletionNotificationQueued' => 'Μια ειδοποίηση ολοκλήρωσης για το ερωτηματολόγιο "{$questionnaire_name}" (που ολοκληρώθηκε από την επαφή "{$contact_name}") τέθηκε στην ουρά για αποστολή στον ρόλο {$role} "{$recipient_name}" ({$recipient_email}).',
