    'SamlKeepRoleTeamsWhenAbsentHelp' => 'Ανενεργό (συνιστάται): μια σύνδεση που παραλείπει το χαρακτηριστικό επαναφέρει το χρήστη στον προεπιλεγμένο ρόλο και χωρίς ομάδες. Ενεργό: ο χρήστης διατηρεί τον τρέχοντα ρόλο και τις ομάδες του. Ενεργοποιήστε το μόνο αν ο IdP σας παραλείπει το χαρακτηριστικό για χρήστες που πρέπει να διατηρήσουν την πρόσβασή τους (το Microsoft Entra το κάνει αυτό για χρήστες χωρίς App Role) και λάβετε υπόψη ότι η αφαίρεση ενός χρήστη από κάθε ομάδα του IdP δεν θα τον υποβιβάσει στο SimpleRisk.',
