    'ControlIdLegacyDatabaseId' => 'Αναγνωριστικό στοιχείου ελέγχου (αναγνωριστικό βάσης δεδομένων, παλαιά εξαγωγή)',
    'ControlIdLegacyColumnNotice' => 'Αυτό το αρχείο χρησιμοποιεί την παλαιού τύπου στήλη Αναγνωριστικό στοιχείου ελέγχου, η οποία περιέχει ακατέργαστα αναγνωριστικά βάσης δεδομένων αντί για τα αναγνωριστικά που εμφανίζει το SimpleRisk. Τα αναγνωριστικά αντιστοιχίστηκαν ως αναγνωριστικά βάσης δεδομένων. Εξαγάγετε ξανά τα στοιχεία ελέγχου για να λάβετε τα εμφανιζόμενα αναγνωριστικά (τη στήλη "Αναγνωριστικό στοιχείου ελέγχου (όπως εμφανίζεται)") για μελλοντικές εισαγωγές.',
    'ControlIdLegacyNotFound' => 'Η γραμμή παραλείφθηκε: κανένα στοιχείο ελέγχου δεν έχει το αναγνωριστικό βάσης δεδομένων "{$id}".',
    'ControlIdHeaderIsLegacy' => 'Δεν έγινε εισαγωγή τίποτα. Η στήλη που έχει αντιστοιχιστεί στο "Αναγνωριστικό στοιχείου ελέγχου (όπως εμφανίζεται)" έχει κεφαλίδα "Αναγνωριστικό στοιχείου ελέγχου", με την οποία οι προηγούμενες εκδόσεις επισημαίνουν τα αναγνωριστικά βάσης δεδομένων των εξαγόμενων στοιχείων ελέγχου. Αντιστοιχίστε αντί γι\' αυτό τη στήλη στο "Αναγνωριστικό στοιχείου ελέγχου (αναγνωριστικό βάσης δεδομένων, παλαιά εξαγωγή)" ή εξαγάγετε ξανά τα στοιχεία ελέγχου για να λάβετε τα εμφανιζόμενα αναγνωριστικά. Αν η στήλη περιέχει αναγνωριστικά 1001 ή μεγαλύτερα, είναι στήλη εμφανιζόμενων αναγνωριστικών: μετονομάστε την κεφαλίδα της σε "Αναγνωριστικό στοιχείου ελέγχου (όπως εμφανίζεται)" και αντιστοιχίστε την ξανά.',
    'ControlIdHeaderIsDisplayed' => 'Δεν έγινε εισαγωγή τίποτα. Η στήλη που έχει αντιστοιχιστεί στο "Αναγνωριστικό στοιχείου ελέγχου (αναγνωριστικό βάσης δεδομένων, παλαιά εξαγωγή)" έχει κεφαλίδα "Αναγνωριστικό στοιχείου ελέγχου (όπως εμφανίζεται)", επομένως περιέχει εμφανιζόμενα αναγνωριστικά. Αντιστοιχίστε αντί γι\' αυτό τη στήλη στο "Αναγνωριστικό στοιχείου ελέγχου (όπως εμφανίζεται)".',
